const {getDatabase}=require('../_db');const {currentUser}=require('./_auth');
module.exports=async function handler(req,res){if(req.method!=='GET')return res.status(405).json({error:'Método não permitido'});if(!currentUser(req))return res.status(401).json({error:'Sessão expirada.'});try{const sql=getDatabase();const rows=await sql`SELECT id,nome,email,perfil,ativo FROM usuarios_atendimento WHERE ativo=TRUE ORDER BY nome ASC`;return res.status(200).json({atendentes:rows})}catch(error){console.error(error);return res.status(500).json({error:'Não foi possível carregar os atendentes.'})}};
